import boto3
import os
from google.cloud import language_v1
import openai

def get_textract_client():
    return boto3.client('textract', region_name=os.environ.get('AWS_REGION', 'us-east-1'))

def get_translate_client():
    return boto3.client('translate', region_name=os.environ.get('AWS_REGION', 'us-east-1'))

def get_comprehend_client():
    return boto3.client('comprehend', region_name=os.environ.get('AWS_REGION', 'us-east-1'))

def get_google_nl_client():
    # Google Cloud Natural Language API client
    # Assumes GOOGLE_APPLICATION_CREDENTIALS environment variable is set or credentials are otherwise available
    return language_v1.LanguageServiceClient()

def get_openai_client():
    # OpenAI client
    # Assumes OPENAI_API_KEY environment variable is set
    return openai.OpenAI()

from typing import List, Dict, Any

# Basic models for extracted content - can be expanded as needed

class ExtractedText:
    def __init__(self, text: str, block_type: str = "LINE", confidence: float = None):
        self.text = text
        self.block_type = block_type
        self.confidence = confidence

    def to_dict(self):
        return {"text": self.text, "block_type": self.block_type, "confidence": self.confidence}

class ExtractedLayoutElement:
    def __init__(self, element_type: str, text: str = None, geometry: Dict = None, confidence: float = None):
        self.element_type = element_type # e.g., TITLE, PARAGRAPH, LIST, TABLE, FIGURE
        self.text = text
        self.geometry = geometry
        self.confidence = confidence

    def to_dict(self):
        return {"element_type": self.element_type, "text": self.text, "geometry": self.geometry, "confidence": self.confidence}

class ExtractedTableCell:
    def __init__(self, text: str, row_index: int, column_index: int, row_span: int = 1, column_span: int = 1, confidence: float = None):
        self.text = text
        self.row_index = row_index
        self.column_index = column_index
        self.row_span = row_span
        self.column_span = column_span
        self.confidence = confidence

    def to_dict(self):
        return {"text": self.text, "row_index": self.row_index, "column_index": self.column_index, "row_span": self.row_span, "column_span": self.column_span, "confidence": self.confidence}

class ExtractedTable:
    def __init__(self, cells: List[ExtractedTableCell], geometry: Dict = None, confidence: float = None):
        self.cells = cells
        self.geometry = geometry
        self.confidence = confidence

    def to_dict(self):
        return {"cells": [cell.to_dict() for cell in self.cells], "geometry": self.geometry, "confidence": self.confidence}

class ExtractedKeyValuePair:
    def __init__(self, key: str, value: str, key_geometry: Dict = None, value_geometry: Dict = None, confidence: float = None):
        self.key = key
        self.value = value
        self.key_geometry = key_geometry
        self.value_geometry = value_geometry
        self.confidence = confidence

    def to_dict(self):
        return {"key": self.key, "value": self.value, "key_geometry": self.key_geometry, "value_geometry": self.value_geometry, "confidence": self.confidence}

import boto3
from document_client import get_textract_client
from document_models import ExtractedTable, ExtractedTableCell
from typing import List, Dict, Any

def extract_tables(image_bytes: bytes) -> List[ExtractedTable]:
    """
    Extracts table cells and row structure from a document using AWS Textract.
    """
    textract_client = get_textract_client()
    response = textract_client.analyze_document(
        Document={'Bytes': image_bytes},
        Features=['TABLES']
    )

    tables: List[ExtractedTable] = []
    blocks = response.get('Blocks', [])

    # Helper to find text for a block ID
    block_map = {block['Id']: block for block in blocks}

    for block in blocks:
        if block['BlockType'] == 'TABLE':
            table_cells: List[ExtractedTableCell] = []
            for relationship in block.get('Relationships', []):
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        cell_block = block_map.get(child_id)
                        if cell_block and cell_block['BlockType'] == 'CELL':
                            # Find text content for the cell
                            cell_text = ""
                            for cell_rel in cell_block.get('Relationships', []):
                                if cell_rel['Type'] == 'CHILD':
                                    for word_id in cell_rel['Ids']:
                                        word_block = block_map.get(word_id)
                                        if word_block and word_block['BlockType'] == 'WORD':
                                            cell_text += word_block.get('Text', '') + " "
                            cell_text = cell_text.strip()

                            table_cells.append(ExtractedTableCell(
                                text=cell_text,
                                row_index=cell_block['RowIndex'],
                                column_index=cell_block['ColumnIndex'],
                                row_span=cell_block.get('RowSpan', 1),
                                column_span=cell_block.get('ColumnSpan', 1),
                                confidence=cell_block.get('Confidence')
                            ))
            tables.append(ExtractedTable(
                cells=table_cells,
                geometry=block.get('Geometry'),
                confidence=block.get('Confidence')
            ))
    return tables

import boto3
from document_client import get_textract_client
from document_models import ExtractedKeyValuePair
from typing import List, Dict, Any

def extract_key_values(image_bytes: bytes) -> List[ExtractedKeyValuePair]:
    """
    Extracts key-value pairs from a form-like document using AWS Textract.
    """
    textract_client = get_textract_client()
    response = textract_client.analyze_document(
        Document={'Bytes': image_bytes},
        Features=['FORMS']
    )

    key_value_pairs: List[ExtractedKeyValuePair] = []
    blocks = response.get('Blocks', [])

    # Helper to find text for a block ID
    block_map = {block['Id']: block for block in blocks}

    def get_text_from_ids(ids: List[str]) -> str:
        text = ""
        for id in ids:
            block = block_map.get(id)
            if block and block['BlockType'] == 'WORD':
                text += block.get('Text', '') + " "
        return text.strip()

    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET' and 'KEY' in block['EntityTypes']:
            key_text = ""
            value_text = ""
            key_geometry = None
            value_geometry = None
            confidence = block.get('Confidence')

            for relationship in block.get('Relationships', []):
                if relationship['Type'] == 'CHILD':
                    key_text = get_text_from_ids(relationship['Ids'])
                    key_block_id = relationship['Ids'][0] if relationship['Ids'] else None
                    if key_block_id and block_map.get(key_block_id):
                        key_geometry = block_map.get(key_block_id).get('Geometry')

                elif relationship['Type'] == 'VALUE':
                    for value_id in relationship['Ids']:
                        value_block = block_map.get(value_id)
                        if value_block and 'VALUE' in value_block['EntityTypes']:
                            for value_relationship in value_block.get('Relationships', []):
                                if value_relationship['Type'] == 'CHILD':
                                    value_text = get_text_from_ids(value_relationship['Ids'])
                                    value_geometry = value_block.get('Geometry')
                                    break # Assuming one value per key

            if key_text or value_text:
                key_value_pairs.append(ExtractedKeyValuePair(
                    key=key_text,
                    value=value_text,
                    key_geometry=key_geometry,
                    value_geometry=value_geometry,
                    confidence=confidence
                ))

    return key_value_pairs
